def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """
    Given a string s and an integer k, partition s into k substrings such that the sum 
    of the number of letter changes required to turn each substring into a semi-palindrome 
    is minimized. Return the minimum number of letter changes required.

    Args:
        s: A string consisting only of lowercase English letters (2 <= len(s) <= 200)
        k: Number of substrings to partition into (1 <= k <= len(s) / 2)

    Returns:
        The minimum number of letter changes required to make all k substrings semi-palindromes.
    """
    def is_semi_palindrome(substring):
        """Check if a substring is a semi-palindrome."""
        n = len(substring)
        for d in range(1, n):
            if n % d == 0:
                groups = [substring[i:i+d] for i in range(0, n, d)]
                if all(group == group[::-1] for group in groups):
                    return True
        return False

    def count_changes(substring):
        """Count the number of letter changes required to make a substring a semi-palindrome."""
        n = len(substring)
        min_changes = float('inf')
        for d in range(1, n):
            if n % d == 0:
                groups = [substring[i:i+d] for i in range(0, n, d)]
                changes = 0
                for group in groups:
                    changes += sum(1 for i in range(len(group)//2) if group[i] != group[-i-1])
                min_changes = min(min_changes, changes)
        return min_changes

    def dp(i, k):
        """Dynamic programming function to find the minimum number of letter changes."""
        if k == 0:
            if is_semi_palindrome(s[i:]):
                return 0
            else:
                return float('inf')
        if i == len(s):
            return float('inf')
        min_changes = float('inf')
        for j in range(i+2, len(s)+1):
            changes = count_changes(s[i:j]) + dp(j, k-1)
            min_changes = min(min_changes, changes)
        return min_changes

    return dp(0, k)
